### Sharpness-Aware Minimization (SAM)
#  img_exps/sam.py  (verbatim)

import torch
import torch.nn as nn

class SAM(torch.optim.Optimizer):
    def __init__(self, params, base_optimizer, rho=0.05, adaptive=False, **kwargs):
        assert rho >= 0.0, f"Invalid rho, should be non-negative: {rho}"
        defaults = dict(rho=rho, adaptive=adaptive, **kwargs)
        super(SAM, self).__init__(params, defaults)
        self.base_optimizer = base_optimizer(self.param_groups, **kwargs)
        self.param_groups = self.base_optimizer.param_groups

    @torch.no_grad()
    def first_step(self, zero_grad=False):
        grad_norm = self._grad_norm()
        for group in self.param_groups:
            scale = group["rho"] / (grad_norm + 1e-12)
            for p in group["params"]:
                if p.grad is None: continue
                self.state[p]["old_p"] = p.data.clone()
                e_w = (torch.pow(p, 2) if group["adaptive"] else 1.0) * p.grad * scale.to(p)
                p.add_(e_w)                      # w  <-  w + e(w)
        if zero_grad: self.zero_grad()

    @torch.no_grad()
    def second_step(self, zero_grad=False):
        for group in self.param_groups:
            for p in group["params"]:
                if p.grad is None: continue
                p.data = self.state[p]["old_p"]  # reset to w
        self.base_optimizer.step()               # sharpness-aware update
        if zero_grad: self.zero_grad()

    @torch.no_grad()
    def step(self, closure=None):
        assert closure is not None, "SAM requires closure"
        closure = torch.enable_grad()(closure)
        self.first_step(zero_grad=True)
        closure()
        self.second_step()

    def _grad_norm(self):
        shared_device = self.param_groups[0]["params"][0].device
        norm = torch.norm(torch.stack([
            ((torch.abs(p) if group["adaptive"] else 1.0) * p.grad).norm(p=2).to(shared_device)
            for group in self.param_groups for p in group["params"] if p.grad is not None]), p=2)
        return norm


def disable_running_stats(model):
    def _disable(module):
        if isinstance(module, nn.BatchNorm2d):
            module.backup_momentum = module.momentum
            module.momentum = 0
    model.apply(_disable)

def enable_running_stats(model):
    def _enable(module):
        if isinstance(module, nn.BatchNorm2d) and hasattr(module, "backup_momentum"):
            module.momentum = module.backup_momentum
    model.apply(_enable)


### Loss-Landscape utilities  (analysis/loss_landscape.py)

import numpy as np, torch
from tqdm import tqdm
from analysis.utils import flatten_parameters, assign_params

def calculate_loss_contours(model1, model2, model3, dataloader, eval_fn,
                            device, granularity=20, margin=0.2):
    """Compute 2-D loss/accuracy surface on plane through three checkpoints."""
    w1 = flatten_parameters(model1).to(device)
    w2 = flatten_parameters(model2).to(device)
    w3 = flatten_parameters(model3).to(device)
    # axis u (x)  &  v (y)
    u = (w3 - w1); dx = torch.norm(u).item(); u /= dx
    v = (w2 - w1); v -= torch.dot(u, v) * u; dy = torch.norm(v).item(); v /= dy
    alphas = np.linspace(0.0 - margin, 1.0 + margin, granularity)
    betas  = np.linspace(0.0 - margin, 1.0 + margin, granularity)
    losses, accuracies, grid = np.zeros((granularity, granularity)), np.zeros_like(losses), np.zeros((granularity, granularity, 2))
    progress = tqdm(total=granularity*granularity)
    for i, a in enumerate(alphas):
        for j, b in enumerate(betas):
            p = w1 + a*dx*u + b*dy*v
            assign_params(model1, p)
            metrics = eval_fn(model1, dataloader, device)
            grid[i,j] = [a*dx, b*dy]; losses[i,j]=metrics['loss']; accuracies[i,j]=metrics['accuracy']
            progress.update()
    progress.close()
    return dict(grid=grid.tolist(), losses=losses.tolist(), accuracies=accuracies.tolist())


### Sharpness metric (analysis/sharpness.py)

import copy, numpy as np, torch, logging
from scipy import optimize
from analysis.utils import flatten_parameters, flatten_gradients

def sharpness(model, criterion_fn, A, epsilon=1e-3, p=0):
    """Keskar et al. (2017) sharpness implementation."""
    run_fn = _create_run(model, A, criterion_fn)
    bounds = _compute_bounds(model, A, epsilon)
    dim = flatten_parameters(model).shape[0] if p==0 else p
    y = optimize.minimize(lambda x: run_fn(x), np.zeros(dim), method='L-BFGS-B', bounds=bounds, jac=True, options={'maxiter':10}).x.astype(np.float32)
    model_copy = copy.deepcopy(model); _apply_diffs(model_copy, A@y if A is not 1 else y)
    max_loss = criterion_fn(model_copy)['loss']; base_loss = criterion_fn(model)['loss']
    return 100*(max_loss-base_loss)/(1+base_loss)

# helper routines -----------------------------------------------------

def _compute_bounds(model, A, eps):
    x = flatten_parameters(model)
    if A is 1: b = eps*(np.abs(x)+1)
    else: b = eps*(np.abs(np.linalg.lstsq(A,x,rcond=None)[0])+1)
    return optimize.Bounds(-b, b)

def _apply_diffs(model, diffs):
    idx=0
    for p in model.parameters():
        if p.requires_grad:
            n=p.nelement(); p.data = p.data + torch.tensor(diffs[idx:idx+n].reshape(p.shape)).to(p.device); idx+=n

def _create_run(model, A, criterion_fn):
    def run(y):
        y=y.astype(np.float32); m=copy.deepcopy(model); m.zero_grad();
        _apply_diffs(m, y if A is 1 else A@y)
        metrics=criterion_fn(m); obj=-metrics['loss']; grad=-metrics['gradients'];
        if A is not 1: grad = grad@A
        logging.info("Loss: %f", obj)
        return obj, grad.astype(np.float64)
    return run


