def train_single_epoch(algo, model, dataloader, criterion, optimizer,
                       classes_per_task, args, task_id=None, sam=False):
    model.train()
    for X, y in dataloader:
        model.zero_grad(); X=X.to(args.device); y=y.to(args.device)
        if sam: enable_running_stats(model)
        if args.method=='er':
            if task_id>0:
                mem_x, mem_y, mem_task = algo.sample(args.batch_size)
                mem_pred = model(mem_x, None)
                mem_pred = extract_logits(mem_pred, mem_task, classes_per_task, args.device)
                criterion(mem_pred, mem_y).backward()
            algo.add_reservoir(X,y,None,task_id)
        elif args.method=='ewc':
            (args.lambd*algo.penalty(model)).backward()
        elif args.method=='agem':
            model = algo.observe_agem(model,X,task_id,y)
        if args.method!='agem':
            criterion(model(X,task_id),y).backward()
        if sam:
            optimizer.first_step(zero_grad=True)
            disable_running_stats(model)
            criterion(model(X,task_id),y).backward()
            optimizer.second_step(zero_grad=True)
        else:
            optimizer.step()


def run_cl(args, dataloaders, task_split, num_classes, classes_per_task):
    model = ResNet(num_classes, classes_per_task, layers=18, pretrained=args.pretrained).to(args.device)
    optimizer = SAM(model.parameters(), torch.optim.SGD, rho=args.rho, lr=args.lr) if args.sam else torch.optim.SGD(model.parameters(), lr=args.lr)
    criterion = torch.nn.CrossEntropyLoss().to(args.device)
    algo=None
    if args.method=='er': algo=ER(args, num_classes)
