# img_exps/existing_methods/ewc.py – Elastic Weight Consolidation
class EWC(object):
    def __init__(self, model, criterion):
        self.model, self.criterion = model, criterion
        self.params = {n:p for n,p in model.named_parameters() if p.requires_grad}
        self._means, self.precision = {},{}
        for n,p in self.params.items():
            self._means[n]=p.data.clone(); self.precision[n]=p.data.clone().zero_()
    def update(self, model, t, loader):
        # estimate Fisher diagonal
        model.eval();
        for n,p in self.params.items(): self._means[n]=p.data.clone()
        for x,y in loader:
            model.zero_grad(); loss=self.criterion(model(x.cuda(),t),y.cuda()); loss.backward()
            for n,p in model.named_parameters(): self.precision[n]+= (p.grad.data**2)
            break;  self.precision={n:p/(t+1) for n,p in self.precision.items()}
    def penalty(self, model):
        return sum((self.precision[n]*(p-self._means[n])**2).sum() for n,p in model.named_parameters())

